static int ck_debug_import_checkpoint(CKModel *model, int layer, const char *checkpoint, float *data, size_t count) {
    const char *path = getenv("CK_DEBUG_IMPORT_HIDDEN");
    const char *layer_text = getenv("CK_DEBUG_IMPORT_LAYER");
    const char *wanted_checkpoint = getenv("CK_DEBUG_IMPORT_CHECKPOINT");
    if (!path || !path[0] || !layer_text || !layer_text[0] ||
        !wanted_checkpoint || !wanted_checkpoint[0] ||
        !model || !checkpoint || !data || count == 0) return 0;
    char *end = NULL;
    long wanted = strtol(layer_text, &end, 10);
    if (end == layer_text || *end != '\0' || wanted != layer ||
        strcmp(wanted_checkpoint, checkpoint) != 0) return 0;
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "[CK X-ray] cannot open checkpoint input: %s\n", path);
        return -1;
    }
    const size_t got = fread(data, sizeof(float), count, f);
    const int extra = fgetc(f);
    fclose(f);
    if (got != count || extra != EOF) {
        fprintf(stderr,
                "[CK X-ray] checkpoint input size mismatch layer=%d checkpoint=%s expected=%zu got=%zu extra=%d\n",
                layer, checkpoint, count, got, extra != EOF);
        return -1;
    }
    fprintf(stderr, "[CK X-ray] imported layer %d checkpoint %s (%zu floats)\n",
            layer, checkpoint, count);
    return 1;
}

static int ck_debug_hidden_name_in_list(const char *list, const char *name) {
    if (!list || !list[0] || !name) return 1;
    const size_t name_len = strlen(name);
    const char *cursor = list;
    while (*cursor) {
        while (*cursor == ',' || *cursor == ' ' || *cursor == '	') cursor++;
        const char *start = cursor;
        while (*cursor && *cursor != ',') cursor++;
        const char *end = cursor;
        while (end > start && (end[-1] == ' ' || end[-1] == '	')) end--;
        if ((size_t)(end - start) == name_len && memcmp(start, name, name_len) == 0) return 1;
        if (*cursor == ',') cursor++;
    }
    return 0;
}

static void ck_debug_export_hidden(CKModel *model, int layer, const char *name, const float *data, int count) {
    const char *dir = getenv("CK_DEBUG_EXPORT_HIDDEN");
    if (!dir || !dir[0] || !model || !name || !data || count <= 0) return;
    const char *layer_filter = getenv("CK_DEBUG_EXPORT_HIDDEN_LAYER");
    if (layer_filter && layer_filter[0]) {
        char *end = NULL;
        long wanted = strtol(layer_filter, &end, 10);
        if (end != layer_filter && layer != (int)wanted) return;
    }
    const char *name_filter = getenv("CK_DEBUG_EXPORT_HIDDEN_NAME");
    if (name_filter && name_filter[0] && strcmp(name_filter, name) != 0) return;
    const char *name_filters = getenv("CK_DEBUG_EXPORT_HIDDEN_NAMES");
    if (name_filters && name_filters[0] && !ck_debug_hidden_name_in_list(name_filters, name)) return;
    char path[1024];
    int n = snprintf(path, sizeof(path), "%s/tok_%04d_layer_%03d_%s.f32",
                     dir, model->pos, layer, name);
    if (n <= 0 || (size_t)n >= sizeof(path)) return;
    FILE *f = fopen(path, "wb");
    if (!f) return;
    (void)fwrite(data, sizeof(float), (size_t)count, f);
    fclose(f);
}

static int do_init(const char *weights_path) {
    if (g_model) return 0;
    g_model = calloc(1, sizeof(CKModel));
    if (!g_model) {
        fprintf(stderr, "ck_model_init: failed to allocate CKModel struct (%zu bytes)\n", sizeof(CKModel));
        return -1;
    }

    if (ck_bump_alloc_init(&g_model->bump_alloc, weights_path,
                           BUMP_TOTAL_SIZE, BUMP_WEIGHTS_OFFSET, BUMP_ACT_OFFSET) != 0) {
        fprintf(stderr,
                "ck_model_init: failed to allocate bump arena (%zu bytes, %.2f MiB)\n",
                (size_t)BUMP_TOTAL_SIZE,
                (double)BUMP_TOTAL_SIZE / (1024.0 * 1024.0));
        free(g_model);
        g_model = NULL;
        return -1;
    }
    g_model->bump = g_model->bump_alloc.base;
    g_model->bump_size = g_model->bump_alloc.total_size;
    memset(g_model->bump + BUMP_ACT_OFFSET, 0, g_model->bump_size - BUMP_ACT_OFFSET);

    g_model->bump_weights = g_model->bump; /* Manifest runtime offsets are absolute. */
    g_model->activations = (float*)(g_model->bump + BUMP_ACT_OFFSET);
#ifdef A_KV_CACHE
    g_model->kv_cache = (float*)(g_model->bump + A_KV_CACHE);
    g_model->kv_cache_f16 = (uint16_t*)(g_model->bump + A_KV_CACHE);
#else
    g_model->kv_cache = NULL;
    g_model->kv_cache_f16 = NULL;
#endif
#ifdef A_ROPE_CACHE
    g_model->rope_cos = (float*)(g_model->bump + A_ROPE_CACHE);
#else
    size_t rope_cache_elems = (size_t)MAX_SEQ_LEN * (size_t)ROTARY_DIM;
    g_model->rope_cos = (float*)calloc(rope_cache_elems, sizeof(float));
    if (!g_model->rope_cos) {
        fprintf(stderr, "ck_model_init: failed to allocate RoPE cache (%zu floats)\n", rope_cache_elems);
        ck_bump_alloc_free(&g_model->bump_alloc);
        free(g_model);
        g_model = NULL;
        return -1;
    }
#endif
    g_model->rope_sin = g_model->rope_cos + MAX_SEQ_LEN * ROTARY_DIM / 2;
#ifdef A_LOGITS
    g_model->logits = (float*)(g_model->bump + A_LOGITS);
#else
    g_model->logits = NULL;
#endif
    g_model->pos = 0;
    g_model->rope_pos = 0;
    g_model->bridge_has_explicit_positions = 0;

    /* v8 fallback: precompute RoPE cache when init_call.json was not provided */
    rope_precompute_cache(
        (float*)(g_model->bump + A_ROPE_CACHE),
        (float*)(g_model->bump + A_ROPE_CACHE) + MAX_SEQ_LEN * ROTARY_DIM / 2,
        MAX_SEQ_LEN,
        HEAD_DIM,
        10000.0f,
        ROTARY_DIM,
        "none",
        1.0f
    );

    return 0;
}

static int build_manifest_path(const char *weights_path, char *out, size_t out_sz) {
    const char *slash = strrchr(weights_path, '/');
#ifdef _WIN32
    const char *bslash = strrchr(weights_path, '\\');
    if (!slash || (bslash && bslash > slash)) slash = bslash;
#endif
    if (slash) {
        size_t dir_len = (size_t)(slash - weights_path + 1);
        const char *fname = "weights_manifest.map";
        size_t need = dir_len + strlen(fname) + 1;
        if (need > out_sz) return -1;
        memcpy(out, weights_path, dir_len);
        memcpy(out + dir_len, fname, strlen(fname) + 1);
        return 0;
    }
    if (strlen("weights_manifest.map") + 1 > out_sz) return -1;
    strcpy(out, "weights_manifest.map");
    return 0;
}

static int do_load_manifest(const char *weights_path, const char *manifest_path) {
    int materialize_weights = ck_bump_alloc_needs_weight_materialization(&g_model->bump_alloc);
    #if MANIFEST_OFFSETS_ABSOLUTE
    g_manifest = ck_open_weights_manifest_v8(g_model->bump, weights_path, manifest_path, materialize_weights);
    #else
    g_manifest = ck_open_weights_manifest_v8(g_model->bump_weights, weights_path, manifest_path, materialize_weights);
    #endif
    return g_manifest ? 0 : -1;
}

/* Post-weights initialization (tokenizer, etc.)
 * MUST be called AFTER do_load_manifest() because these ops read from bump memory */
static void do_post_weights_init(void) {
    /* No post-weights init ops (no tokenizer) */
}

static void print_omp_info(void) {
#ifdef _OPENMP
    int max_threads = omp_get_max_threads();
    const char *env = getenv("OMP_NUM_THREADS");
    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    fprintf(stderr, "[OpenMP]   Threads: %d (OMP_NUM_THREADS=%s) | CPU cores: %ld\n",
            max_threads, env ? env : "auto", ncpu);
#else
    fprintf(stderr, "[OpenMP]   Disabled (compiled without -fopenmp)\n");
#endif
}

/* Combined init + load (ck_chat.py expects this signature) */
CK_EXPORT int ck_model_init(const char *weights_path) {
    char manifest_path[4096];
    if (do_init(weights_path) != 0) return -1;
    if (build_manifest_path(weights_path, manifest_path, sizeof(manifest_path)) != 0) return -1;
    if (do_load_manifest(weights_path, manifest_path) != 0) return -1;
    do_post_weights_init();  /* Initialize tokenizer AFTER weights are loaded */
    print_omp_info();
#ifdef CK_PARALLEL_DECODE
    ck_parallel_decode_init();
#endif
#ifdef CK_PARALLEL_PREFILL
    ck_parallel_prefill_init();
#endif
#ifdef CK_PARITY_DUMP
    ck_dump_init(NULL);  /* Initialize parity dumping to ck_parity_dumps/dump.bin */
#endif
    return 0;
}

/* Explicit manifest path (preferred) */
CK_EXPORT int ck_model_init_with_manifest(const char *weights_path, const char *manifest_path) {
    if (do_init(weights_path) != 0) return -1;
    if (do_load_manifest(weights_path, manifest_path) != 0) return -1;
    do_post_weights_init();  /* Initialize tokenizer AFTER weights are loaded */
    print_omp_info();
#ifdef CK_PARALLEL_DECODE
    ck_parallel_decode_init();
#endif
#ifdef CK_PARALLEL_PREFILL
    ck_parallel_prefill_init();
#endif
#ifdef CK_PARITY_DUMP
    ck_dump_init(NULL);
#endif
    return 0;
}

CK_EXPORT void ck_model_free(void) {
    if (!g_model) return;
#ifdef CK_PARALLEL_DECODE
    ck_parallel_decode_shutdown();
#endif
#ifdef CK_PARALLEL_PREFILL
    ck_parallel_prefill_shutdown();
#endif
#ifdef CK_PARITY_DUMP
    ck_dump_close();  /* Close parity dump file */
#endif

    if (g_manifest) {
        ck_unload_manifest_map(g_manifest);
        g_manifest = NULL;
    }
#ifndef A_ROPE_CACHE
    free(g_model->rope_cos);
#endif
    ck_bump_alloc_free(&g_model->bump_alloc);
    free(g_model);
    g_model = NULL;
}

CK_EXPORT void ck_model_kv_cache_reset(void) {
    if (!g_model) return;
    int before_pos = g_model->pos;
    if (g_model->kv_cache && KV_CACHE_SIZE > 0) {
        memset(g_model->kv_cache, 0, KV_CACHE_SIZE);
    }
    memset(g_model->bump + A_RECURRENT_CONV_STATE, 0, 4);
    memset(g_model->bump + A_RECURRENT_SSM_STATE, 0, 4);
    g_model->pos = 0;
    g_model->rope_pos = 0;
    g_model->bridge_has_explicit_positions = 0;
    ck_trace_pos("kv_reset", -1, 0, before_pos, g_model->pos);
}

