CK_EXPORT int ck_model_debug_export_kv_f16(const char *path, int layer) {
    if (!g_model || !path || !path[0] || !g_model->kv_cache_f16) return -1;
    if (layer < 0 || layer >= NUM_LAYERS || g_model->pos < 0 || g_model->pos > MAX_SEQ_LEN) return -2;
    FILE *f = fopen(path, "wb");
    if (!f) return -3;
    const uint32_t header[8] = {
        UINT32_C(0x564b5843), UINT32_C(1), (uint32_t)layer, (uint32_t)g_model->pos,
        (uint32_t)NUM_KV_HEADS, (uint32_t)MAX_SEQ_LEN, (uint32_t)HEAD_DIM, UINT32_C(0)
    };
    if (fwrite(header, sizeof(header), 1, f) != 1) { fclose(f); return -4; }
    const size_t head_stride = (size_t)MAX_SEQ_LEN * (size_t)HEAD_DIM;
    const size_t valid_bytes = (size_t)g_model->pos * (size_t)HEAD_DIM * sizeof(uint16_t);
    const uint16_t *layer_k = g_model->kv_cache_f16 +
        (size_t)(layer * 2) * (size_t)NUM_KV_HEADS * head_stride;
    const uint16_t *layer_v = g_model->kv_cache_f16 +
        (size_t)(layer * 2 + 1) * (size_t)NUM_KV_HEADS * head_stride;
    for (int h = 0; h < NUM_KV_HEADS; ++h) {
        if (fwrite(layer_k + (size_t)h * head_stride, valid_bytes, 1, f) != 1) { fclose(f); return -5; }
    }
    for (int h = 0; h < NUM_KV_HEADS; ++h) {
        if (fwrite(layer_v + (size_t)h * head_stride, valid_bytes, 1, f) != 1) { fclose(f); return -6; }
    }
    fclose(f);
    return 0;
}

static int ck_trace_pos_enabled(void) {
    const char *env = getenv("CK_TRACE_POS");
    return env && atoi(env) != 0;
}

static void ck_trace_pos(const char *stage, int32_t token, int count, int before_pos, int after_pos) {
    if (!ck_trace_pos_enabled()) return;
    fprintf(stderr,
            "[CK_TRACE_POS] %s token=%d count=%d before_pos=%d after_pos=%d rope_pos=%d\n",
            stage ? stage : "?",
            (int)token,
            count,
            before_pos,
            after_pos,
            g_model ? g_model->rope_pos : -1);
}

/* ============================================================================
 * PUBLIC API (compatible with ck_chat.py)
 * ============================================================================ */

/* Embed tokens (prefill) - stores embeddings in activation buffer */
CK_EXPORT int ck_model_embed_tokens(const int32_t *tokens, int count) {
    if (!g_model || !tokens || count <= 0) return -1;
    int before_pos = g_model->pos;
    ck_trace_pos("embed_begin", tokens[0], count, before_pos, g_model->pos);

#ifdef CK_HAS_PREFILL
    /* Use batched prefill for multiple tokens unless the model requires decode replay. */
    if (count > 1 && !(getenv("CK_V8_FORCE_DECODE_PREFILL") && atoi(getenv("CK_V8_FORCE_DECODE_PREFILL")) != 0)) {
        ck_prefill(g_model, tokens, count);
        ck_trace_pos("embed_prefill_end", tokens[count - 1], count, before_pos, g_model->pos);
        return 0;
    }
#endif

    /* Single token or no prefill: process one by one via decode */
    for (int i = 0; i < count; i++) {
        g_ck_skip_decode_logits = (i + 1 < count);
        ck_decode(g_model, tokens[i]);
    }
    g_ck_skip_decode_logits = 0;
    ck_trace_pos("embed_decode_end", tokens[count - 1], count, before_pos, g_model->pos);
    return 0;
}

/* Forward pass (after embed_tokens) */
CK_EXPORT int ck_model_forward(float *output) {
    if (!g_model) return -1;
    /* Logits are already computed by embed_tokens/decode */
    if (output) memcpy(output, g_model->logits, VOCAB_SIZE * sizeof(float));
    return 0;
}

/* Decode single token */
CK_EXPORT int ck_model_decode(int32_t token, float *output) {
    if (!g_model) return -1;
    /* Capture position before decode (ck_decode increments pos at end) */
    int token_pos = g_model->pos;
    ck_trace_pos("decode_begin", token, 1, token_pos, g_model->pos);
    g_ck_skip_decode_logits = 0;
    ck_decode(g_model, token);
    /* Copy logits from position 0 to position token_pos in the logits buffer.
     * This makes the logits buffer match what ck_chat.py expects:
     * logits[token_pos * LOGITS_STRIDE .. (token_pos+1) * LOGITS_STRIDE] */
    if (token_pos > 0) {
        memmove(
            g_model->logits + (size_t)token_pos * 1,
            g_model->logits,
            VOCAB_SIZE * sizeof(float)
        );
    }
    if (output) memcpy(output, g_model->logits + (size_t)token_pos * 1, VOCAB_SIZE * sizeof(float));
    ck_trace_pos("decode_end", token, 1, token_pos, g_model->pos);
    return 0;
}

